ckStrategies\": [\"static_summary_card\"], \"preferredShotTypes\": [\"WIDE_SHOT\", \"CLOSE_UP\"], \"requiredVisualFunctions\": [\"static_summary_card\", \"cta_prompt\"], \"preferredCameraMovements\": [\"STATIC\"]}], \"totalSegments\": 4}, \"categoryExtensions\": {\"discoveredCategoryId\": \"vlog\", \"discoveredCategoryName\": \"日常记录\", \"dynamicExtensionFields\": [{\"fieldName\": \"scene_threshold\", \"fieldType\": \"DOUBLE\", \"fieldValue\": 0.25, \"description\": \"风景vlog判定有效硬切的阈值，超过该值的画面跳变计入正式镜头切换\"}, {\"fieldName\": \"cut_frequency\", \"fieldType\": \"STRING\", \"fieldValue\": \"low_frequency\", \"description\": \"全片以长镜头慢节奏为主，仅在场景跳转时做少量淡入淡出转场，无高频快切\"}, {\"fieldName\": \"motion_effects\", \"fieldType\": \"JSON\", \"fieldValue\": [\"slow_motion\", \"double_exposure_transition\", \"static_lockoff\"], \"description\": \"该品类常用的镜头运动与特效列表\", \"allowedValues\": [\"slow_motion\", \"double_exposure_transition\", \"static_lockoff\"]}, {\"fieldName\": \"audio_style\", \"fieldType\": \"STRING\", \"fieldValue\": \"soft_lyrical_background_music\", \"description\": \"全程以舒缓抒情的纯背景音乐作为听觉支撑，几乎无额外音效和旁白\"}], \"discoveredPromptOverrides\": {\"scriptAnalysis\": \"优先用低机位贴近水面的视角拍摄所有动态场景，最大化放大水面波纹和飞鸟掠水的沉浸感\"}}, \"packagingStructure\": {\"titleCards\": [], \"coverStyles\": [{\"layout\": \"full_scenery\", \"colorTone\": \"#FF7A00\", \"textElements\": []}], \"transitions\": [\"dissolve_fade\", \"double_exposure_mix\"], \"subtitleStyles\": []}}',NULL,NULL,'2026-06-10 19:16:57.143','2026-06-10 19:18:12.229',NULL);
