REPLACE INTO `category_knowledge` (`category_id`, `category_name`, `dynamic_fields`, `prompt_overrides`, `scene_threshold`, `discovered_by_llm`, `confidence_score`, `usage_count`, `created_at`, `updated_at`) VALUES ('editing','剪辑类','[{\"fieldName\": \"cut_frequency\", \"fieldType\": \"STRING\", \"description\": \"剪辑密度跨度极大，开篇舒缓，中段逐步提升，高潮段超高频切镜实现爽感\"}, {\"fieldName\": \"motion_effects\", \"fieldType\": \"JSON\", \"description\": \"该品类常用的镜头运动与特效列表\", \"allowedValues\": [\"speed_ramp\", \"zoom_punch\", \"shake\", \"slow_motion\", \"static_lockoff\", \"extreme_close_up\"]}, {\"fieldName\": \"color_grading\", \"fieldType\": \"STRING\", \"description\": \"描述该品类常见的整体调色风格\"}, {\"fieldName\": \"sync_strategy\", \"fieldType\": \"STRING\", \"description\": \"全片所有镜头切换完全对齐BGM每一个鼓点节拍，实现100%音画同步\"}, {\"fieldName\": \"bpm_range\", \"fieldType\": \"JSON\", \"description\": \"该类高燃混剪内容适配的背景音乐通用节拍范围\"}, {\"fieldName\": \"scene_threshold\", \"fieldType\": \"DOUBLE\", \"description\": \"剪辑类运行时视频拆解可参考的镜头切分阈值，高于该值判定为高切频混剪片段\"}]',NULL,0.4,0,1,8,'2026-05-25 06:47:48.821','2026-06-02 12:45:23.508'),('marketing','营销类','[{\"fieldName\": \"hook_type\", \"fieldType\": \"STRING\", \"description\": \"描述该品类常见的开头钩子类型\"}, {\"fieldName\": \"hook_options\", \"fieldType\": \"JSON\", \"description\": \"该品类可用的钩子策略候选池\", \"allowedValues\": [\"question\", \"pain_point\", \"data_shock\", \"controversy\"]}, {\"fieldName\": \"selling_point_count\", \"fieldType\": \"INTEGER\", \"description\": \"描述该品类内容中常见的核心卖点覆盖数量\"}, {\"fieldName\": \"cta_type\", \"fieldType\": \"STRING\", \"description\": \"描述该品类常用的行动号召类型\"}, {\"fieldName\": \"social_proof_type\", \"fieldType\": \"STRING\", \"description\": \"描述该品类常见的社会认同表达方式\"}]',NULL,0.3,0,1,0,'2026-05-25 06:47:48.821','2026-06-02 12:45:23.685'),('motion_graphics','MG/动态海报类','[{\"fieldName\": \"animation_style\", \"fieldType\": \"STRING\", \"description\": \"采用蓝黑高对比科技配色，叠加悬浮UI光晕效果的全动态文字与界面动效风格\"}, {\"fieldName\": \"text_animations\", \"fieldType\": \"JSON\", \"description\": \"该品类常用的文字动效候选池\", \"allowedValues\": [\"typewriter\", \"slide_in\", \"scale_pop\"]}, {\"fieldName\": \"keyframe_count\", \"fieldType\": \"INTEGER\", \"description\": \"该视频有效展示文字关键帧总数量，平均每1.7秒生成一个新关键帧\"}, {\"fieldName\": \"loopable\", \"fieldType\": \"BOOLEAN\", \"description\": \"描述该品类内容是否通常适合循环播放\"}, {\"fieldName\": \"color_scheme\", \"fieldType\": \"JSON\", \"description\": \"描述该品类常见的整体配色方案结构\"}, {\"fieldName\": \"scene_threshold\", \"fieldType\": \"DOUBLE\", \"description\": \"动态图形类视频判定有效硬切的切分阈值，超过该值的画面跳变计入正式镜头切换\"}]',NULL,0.25,0,1,4,'2026-05-25 06:47:48.821','2026-06-02 12:45:23.864'),('product_review','产品测评','[{\"fieldName\": \"hook_type\", \"fieldType\": \"STRING\", \"description\": \"开篇用反常识的平价产品越级对比观点快速抓取用户注意力\"}, {\"fieldName\": \"selling_point_count\", \"fieldType\": \"INTEGER\", \"description\": \"该类测评视频常规覆盖的核心对比维度总数量\"}, {\"fieldName\": \"cta_type\", \"fieldType\": \"STRING\", \"description\": \"结尾根据不同用户的预算和使用需求分层给出选购推荐引导\"}, {\"fieldName\": \"real_shot_ratio\", \"fieldType\": \"DOUBLE\", \"description\": \"该类测评视频实拍内容占整体视频的比例，几乎全部为实拍产品和出镜内容\"}, {\"fieldName\": \"cut_frequency\", \"fieldType\": \"STRING\", \"description\": \"整体以静态特写长镜头为主，仅在维度切换时做少量快速硬切，大部分段落切分节奏舒缓\"}, {\"fieldName\": \"main_shot_usage\", \"fieldType\": \"JSON\", \"description\": \"该品类核心镜头使用偏好，优先使用固定机位产品特写、户外演示全景、真人出镜口播镜头\", \"allowedValues\": [\"close_up_static\", \"wide_scene\", \"first_person_pov\", \"face_talking_head\"]}, {\"fieldName\": \"operation_demo_order\", \"fieldType\": \"STRING\", \"description\": \"功能演示顺序完全按照普通用户拿到产品后的实际使用逻辑推进\"}, {\"fieldName\": \"audio_style\", \"fieldType\": \"STRING\", \"description\": \"全程无口播旁白，仅使用舒缓背景音乐作为听觉支撑\"}, {\"fieldName\": \"peak_cut_frequency\", \"fieldType\": \"DOUBLE\", \"description\": \"视频最高潮阶段的镜头切分速率，单位次每秒\"}, {\"fieldName\": \"climax_trigger_strategy\", \"fieldType\": \"STRING\", \"description\": \"小高潮通过同操作不同角度的快速硬切实现，无需额外特效加持\"}, {\"fieldName\": \"scene_threshold\", \"fieldType\": \"DOUBLE\", \"description\": \"判定镜头是否属于有效硬切的切分阈值，超过该值的画面跳变计入正式镜头切换\"}, {\"fieldName\": \"contrast_product_count\", \"fieldType\": \"INTEGER\", \"description\": \"该类横向对比测评常规使用的对标产品总数量，适用于多数数码横评内容\", \"allowedValues\": [2, 3, 4, 5]}]','{\"scriptAnalysis\": \"数码测评带货类视频必须优先保证实测画面的真实性，所有参数对比内容必须搭配实拍素材，避免纯空泛口播，通过大牌产品和高性价比产品的中立对比突出主推产品优势，可大幅提升用户信任度与转化效率\"}',0.2,1,0.9,6,'2026-05-26 22:53:00.784','2026-06-02 12:45:24.027'),('short_drama','微短剧','[{\"fieldName\": \"cut_frequency\", \"fieldType\": \"STRING\", \"description\": \"开篇节奏平缓，中段矛盾升级逐步提升切速，高潮段瞬间提升至超高频完成爽点爆发\"}, {\"fieldName\": \"motion_effects\", \"fieldType\": \"JSON\", \"description\": \"该品类常用的镜头运动与特效候选池\", \"allowedValues\": [\"fast_push_pull\", \"high_speed_tracking_slow_motion\"]}, {\"fieldName\": \"scene_threshold\", \"fieldType\": \"DOUBLE\", \"description\": \"判定镜头是否属于有效硬切的切分阈值，超过该值的画面跳变计入正式镜头切换\"}]','{\"scriptAnalysis\": \"优先压缩铺垫叙事时长，直接把冲突密度拉满，用夸张超现实收尾强化用户记忆点\"}',0.25,1,0.9,2,'2026-05-26 22:40:45.507','2026-06-02 12:43:51.784'),('tutorial','教学科普','[{\"fieldName\": \"scene_threshold\", \"fieldType\": \"DOUBLE\", \"description\": \"判定镜头是否属于有效硬切的切分阈值，超过该值的画面跳变计入正式镜头切换\"}, {\"fieldName\": \"hook_type\", \"fieldType\": \"STRING\", \"description\": \"开篇以生活化实拍小动作作为锚点，在动作最具张力的瞬间无缝硬切转入动画名场面，快速建立强反差记忆点\"}, {\"fieldName\": \"selling_point_count\", \"fieldType\": \"INTEGER\", \"description\": \"教程内输出的核心可复用剪辑技巧知识点总数量，包含锚点转场、全片鼓点对齐、名场面素材组合排布\"}, {\"fieldName\": \"cta_type\", \"fieldType\": \"STRING\", \"description\": \"无显性文字引导，通过高完成度样片演示触发观众自行模仿剪辑练习\"}, {\"fieldName\": \"real_shot_ratio\", \"fieldType\": \"DOUBLE\", \"description\": \"本类剪辑教程仅开头极短片段使用实拍内容，剩余全部为第三方影视/动画素材演示\"}, {\"fieldName\": \"cut_frequency\", \"fieldType\": \"STRING\", \"description\": \"开篇实拍段节奏舒缓，转场后节奏逐步提升，高潮段采用极高密度硬切完全匹配音乐鼓点\"}, {\"fieldName\": \"main_shot_usage\", \"fieldType\": \"JSON\", \"description\": \"该类剪辑教程优先使用各类影视素材的全景、中景、特写片段做演示，无真人出镜长口播\", \"allowedValues\": [\"close_up_static\", \"mid_shot\", \"wide_scene\"]}, {\"fieldName\": \"audio_style\", \"fieldType\": \"STRING\", \"description\": \"全程以卡点音乐作为核心听觉驱动，叠加重音打击音效、动作音效增强卡点感知\"}, {\"fieldName\": \"peak_cut_frequency\", \"fieldType\": \"DOUBLE\", \"description\": \"视频高潮阶段的镜头切分速率，单位次每秒\"}, {\"fieldName\": \"climax_trigger_strategy\", \"fieldType\": \"STRING\", \"description\": \"通过所有储备演示素材完全对齐音乐鼓点实现高密度卡点爆发，不需要额外复杂特效加持\"}, {\"fieldName\": \"transition_anchor_mode\", \"fieldType\": \"STRING\", \"description\": \"利用实拍动作的运动轨迹和下一个转场镜头的运动轨迹完全匹配，实现无违和感的无缝硬切转场效果\", \"allowedValues\": [\"motion_lock\", \"color_match\", \"shape_match\"]}]','{\"scriptAnalysis\": \"该类剪辑教程模板核心逻辑为「成品吸引-技巧拆解-全点验证-总结落地」，节奏严格随音乐鼓点线性拉高，所有教学点均配套演示画面，降低学习门槛\"}',0.2,1,0.9,2,'2026-06-07 23:54:58.320','2026-06-07 23:54:58.320'),('vlog','日常记录','[{\"fieldName\": \"scene_threshold\", \"fieldType\": \"DOUBLE\", \"description\": \"风景vlog判定有效硬切的阈值，超过该值的画面跳变计入正式镜头切换\"}, {\"fieldName\": \"cut_frequency\", \"fieldType\": \"STRING\", \"description\": \"全片以长镜头慢节奏为主，仅在场景跳转时做少量淡入淡出转场，无高频快切\"}, {\"fieldName\": \"motion_effects\", \"fieldType\": \"JSON\", \"description\": \"该品类常用的镜头运动与特效列表\", \"allowedValues\": [\"slow_motion\", \"double_exposure_transition\", \"static_lockoff\"]}, {\"fieldName\": \"audio_style\", \"fieldType\": \"STRING\", \"description\": \"全程以舒缓抒情的纯背景音乐作为听觉支撑，几乎无额外音效和旁白\"}]','{\"scriptAnalysis\": \"优先用低机位贴近水面的视角拍摄所有动态场景，最大化放大水面波纹和飞鸟掠水的沉浸感\"}',0.25,1,0.9,1,'2026-06-10 19:18:12.076','2026-06-10 19:18:12.076');
