eraMovement\": \"static\", \"requiredContent\": [\"产品防水测试的水滴飞溅特写\"], \"belongsToSegment\": 1, \"cameraMovementTag\": \"STATIC\"}, {\"shotType\": \"charging_demo_closeup\", \"shotIndex\": 4, \"shotTypeTag\": \"CLOSE_UP\", \"functionHint\": \"detail_showcase\", \"durationRange\": {\"max\": 3, \"min\": 2}, \"cameraMovement\": \"static\", \"requiredContent\": [\"充电线接入产品的特写\"], \"belongsToSegment\": 1, \"cameraMovementTag\": \"STATIC\"}, {\"shotType\": \"multi_angle_operation_closeup\", \"shotIndex\": 5, \"shotTypeTag\": \"CLOSE_UP\", \"functionHint\": \"emotion_push\", \"durationRange\": {\"max\": 1, \"min\": 0.5}, \"cameraMovement\": \"static\", \"requiredContent\": [\"不同角度同操作镜头快速切换\"], \"belongsToSegment\": 2, \"cameraMovementTag\": \"STATIC\"}], \"$schema\": \"video-structure-template/v2\", \"version\": \"1.0.0\", \"category\": \"product_review\", \"templateId\": \"a7d2f9c1-3e5b-4d7f-8a9c-1b2d3e4f5a6b\", \"templateName\": \"数码音频产品卖点分步展示短视频模板\", \"viralFactors\": [{\"weight\": 0.85, \"factorName\": \"卖点直观可视化\", \"description\": \"所有产品优势都通过实际操作演示直接呈现，搭配对应文字说明，用户可在短时间内快速get产品核心价值\"}, {\"weight\": 0.7, \"factorName\": \"极简舒适视觉风格\", \"description\": \"全片统一低饱和浅色调，画面干净无冗余元素，观看体验舒适无负担，符合数码产品目标用户的审美偏好\"}], \"rhythmStructure\": {\"paceCurve\": [{\"note\": \"开篇慢节奏展示产品第一印象\", \"pace\": \"medium\", \"timePercent\": 0}, {\"note\": \"逐步推进各卖点演示\", \"pace\": \"medium\", \"timePercent\": 20}, {\"note\": \"充电、防水等卖点镜头节奏平缓\", \"pace\": \"slow\", \"timePercent\": 70}, {\"note\": \"多镜头快切形成小高潮\", \"pace\": \"fast\", \"timePercent\": 90}, {\"note\": \"收尾回归平缓\", \"pace\": \"medium\", \"timePercent\": 100}], \"overallPace\": \"medium\", \"beatSyncPoints\": [{\"type\": \"visual_hit\", \"timePercent\": 90}], \"avgShotDuration\": 2.2, \"climaxPositions\": [{\"endPercent\": 95, \"startPercent\": 85}], \"transitionStyles\": [\"hard_cut_dominant\"]}, \"scriptStructure\": {\"segments\": [{\"role\": \"hook\", \"label\": \"产品外观引入\", \"shotCount\": {\"max\": 3, \"min\": 2}, \"scriptHint\": \"开篇带出产品定位和极简