Movement\": \"static\", \"requiredContent\": [\"居中逐字渐显的主题文字\", \"暗场中心聚光背景\"], \"belongsToSegment\": 0, \"cameraMovementTag\": \"STATIC\"}, {\"shotType\": \"mid_shot\", \"shotIndex\": 1, \"shotTypeTag\": \"MID_SHOT\", \"functionHint\": \"detail_showcase\", \"durationRange\": {\"max\": 6, \"min\": 4}, \"cameraMovement\": \"static\", \"requiredContent\": [\"悬浮展示的多组商品卡片界面\"], \"belongsToSegment\": 1, \"cameraMovementTag\": \"STATIC\"}, {\"shotType\": \"mid_shot\", \"shotIndex\": 2, \"shotTypeTag\": \"MID_SHOT\", \"functionHint\": \"detail_showcase\", \"durationRange\": {\"max\": 5, \"min\": 3}, \"cameraMovement\": \"static\", \"requiredContent\": [\"带数据图表的管理仪表盘界面\"], \"belongsToSegment\": 1, \"cameraMovementTag\": \"STATIC\"}, {\"shotType\": \"mid_shot\", \"shotIndex\": 3, \"shotTypeTag\": \"MID_SHOT\", \"functionHint\": \"detail_showcase\", \"durationRange\": {\"max\": 5, \"min\": 3}, \"cameraMovement\": \"static\", \"requiredContent\": [\"数据库结构字段展示界面\"], \"belongsToSegment\": 1, \"cameraMovementTag\": \"STATIC\"}, {\"shotType\": \"mid_shot\", \"shotIndex\": 4, \"shotTypeTag\": \"MID_SHOT\", \"functionHint\": \"benefit_recall\", \"durationRange\": {\"max\": 4, \"min\": 3}, \"cameraMovement\": \"static\", \"requiredContent\": [\"全平台UI模块联动全景阵列\"], \"belongsToSegment\": 1, \"cameraMovementTag\": \"STATIC\"}, {\"shotType\": \"mid_shot\", \"shotIndex\": 5, \"shotTypeTag\": \"CLOSE_UP\", \"functionHint\": \"cta_prompt\", \"durationRange\": {\"max\": 5, \"min\": 3}, \"cameraMovement\": \"static\", \"requiredContent\": [\"渐变几何图形品牌logo搭配品牌名称\"], \"belongsToSegment\": 2, \"cameraMovementTag\": \"STATIC\"}], \"$schema\": \"video-structure-template/v2\", \"version\": \"1.0.0\", \"category\": \"motion_graphics\", \"templateId\": \"7e2d9f4a-1c3b-4d5e-8f9a-0b7c6d5e4f3a\", \"templateName\": \"蓝黑科技风低代码电商建站全链路MG演示模板\", \"viralFactors\": [{\"weight\": 0.85, \"factorName\": \"精准需求匹配\", \"description\": \"精准瞄准想要快速搭建副业电商站点的目标用户，全程无冗余信息，直观展示零代码建站的全流程能力，大幅降低用户的使用学习心理门槛\"}, {\"weight\": 0.75, 