\"static\", \"requiredContent\": [\"逆光树框日落\", \"水面金色波纹\"], \"belongsToSegment\": 1, \"cameraMovementTag\": \"STATIC\"}, {\"shotType\": \"full_body\", \"shotIndex\": 3, \"shotTypeTag\": \"WIDE_SHOT\", \"functionHint\": \"人文情绪展示\", \"durationRange\": {\"max\": 4, \"min\": 3}, \"cameraMovement\": \"static\", \"requiredContent\": [\"浅色穿搭人物站在湖畔\", \"抬手喂鸟动作\"], \"belongsToSegment\": 2, \"cameraMovementTag\": \"STATIC\"}, {\"shotType\": \"wide_shot\", \"shotIndex\": 4, \"shotTypeTag\": \"WIDE_SHOT\", \"functionHint\": \"静态风光收束\", \"durationRange\": {\"max\": 5, \"min\": 3}, \"cameraMovement\": \"static\", \"requiredContent\": [\"孤树伫立湖面\", \"落日远山背景\"], \"belongsToSegment\": 3, \"cameraMovementTag\": \"STATIC\"}, {\"shotType\": \"static\", \"shotIndex\": 5, \"shotTypeTag\": \"CLOSE_UP\", \"functionHint\": \"平台引导提示\", \"durationRange\": {\"max\": 3, \"min\": 2}, \"cameraMovement\": \"static\", \"requiredContent\": [\"平台搜索引导界面\"], \"belongsToSegment\": 3, \"cameraMovementTag\": \"STATIC\"}], \"$schema\": \"video-structure-template/v2\", \"version\": \"1.0.0\", \"category\": \"vlog\", \"templateId\": \"7a9f2d3c-8e4b-41a9-927c-6d5e3f1a7b8c\", \"templateName\": \"治愈湖光日落慢节奏风光情绪片模板\", \"viralFactors\": [{\"weight\": 0.9, \"factorName\": \"极致治愈情绪共鸣\", \"description\": \"高级的青橙日落色调搭配流畅的慢镜头，把湖光飞鸟的松弛度假感拉满，精准击中当代用户向往逃离压力、体验慢生活的情绪需求，极易引发观众收藏转发。\"}], \"rhythmStructure\": {\"paceCurve\": [{\"note\": \"开篇飞鸟动态带轻微流动感，节奏中等快速引入场景\", \"pace\": \"medium\", \"timePercent\": 0}, {\"note\": \"风光展开段全部使用固定长镜头，节奏大幅放缓营造松弛沉浸式体验\", \"pace\": \"slow\", \"timePercent\": 30}, {\"note\": \"人物出场情绪抬升，节奏小幅上扬，抵达全片情绪顶点\", \"pace\": \"medium\", \"timePercent\": 65}, {\"note\": \"收尾静态画面节奏回落，让观众情绪慢慢平复完成沉浸\", \"pace\": \"slow\", \"timePercent\": 85}], \"overallPace\": \"slow\", \"beatSyncPoints\": [{\"type\": \"climax_hit\", \"timePercent\": 60}, {\"type\": \"visual_hit\", \"timePercent\": 92}], \"avgShotDuration\": 4.2, \"climaxPositions\": [{\"endPercent\": 75, \"startPercent\": 60}], \"transitionStyles\": [\"fade_transition_dominant\", \"soft_double_exposure\"]}, \"scriptStructure\": {\"segments\": [{\"role\": \"hook\", \"label\": \"开篇秋林飞鸟入场\", \"shotCount\": {\"max\": 6, \"min\": 4}, \"scriptHint\": \"开篇机位压低贴近湖面，捕捉飞鸟掠水起飞的动态，背景保留秋日橙红杉林层次，快速输出核心视觉记忆点。\", \"description\": \"用贴近湖面的低角度动态画面，展现飞鸟群飞、红杉倒映水面的核心风光元素，快速建立治愈松弛的第一印象，抓住观众注意力。\", \"segmentIndex\": 0, \"durationRange\": {\"max\": 9, \"min\": 7}, \"durationWeight\": 0.3, \"packagingDensity\": \"none\", \"requiredElements\": [\"流动水面波纹\", \"飞鸟飞行动态\", \"秋季红杉背景\"], \"subtitleStrategy\": \"none\", \"fallbackStrategies\": [\"reuse_existing_material\"], \"preferredShotTypes\": [\"WIDE_SHOT\", \"MID_SHOT\"], \"requiredVisualFunctions\": [\"subject_intro\", \"emotion_push\"], \"preferredCameraMovements\": [\"STATIC\", \"PAN\"]}, {\"role\": \"body\", \"label\": \"日落风光层次展开\", \"shotCount\": {\"max\": 5, \"min\": 3}, \"scriptHint\": \"利用画面前景遮挡自然引入落日光源，让阳光穿过枝叶形成星芒效果，水面保留完整的落日金色反光带。\", \"description\": \"依次切换不同视角的日落湖景画面，从前景树框逆光日落到无遮挡开阔湖面全景，逐步抬升暖金色的氛围感，丰富画面层次。\", \"segmentIndex\": 1, \"durationRange\": {\"max\": 9, \"min\": 7}, \"durationWeight\": 0.3, \"packagingDensity\": \"none\", \"requiredElements\": [\"水面落日反光带\", \"逆光枝叶星芒效果\"], \"subtitleStrategy\": \"none\", \"fallbackStrategies\": [\"reorder_structure\"], \"preferredShotTypes\": [\"WIDE_SHOT\"], \"requiredVisualFunctions\": [\"emotion_push\", \"detail_showcase\"], \"preferredCameraMovements\": [\"STATIC\", \"ZOOM_IN\"]}, {\"role\": \"climax\", \"label\": \"人文情绪顶点\", \"shotCount\": {\"max\": 2, \"min\": 1}, \"scriptHint\": \"保留身后日落湖面的背景光，让人物身上打上柔和的金边侧光，周围环绕多只飞鸟，强化温馨氛围感。\", \"description\": \"通过双重曝光淡入过渡到浅色系穿搭的人物站在湖畔抬手喂鸟的画面，把纯风光的松弛感升级成带人文温度的治愈情绪高潮。\", \"segmentIndex\": 2, \"durationRange\": {\"max\": 5, \"min\": 4}, \"durationWeight\": 0.18, \"packagingDensity\": \"none\", \"requiredElements\": [\"人物抬手持食喂鸟\", \"飞鸟环绕飞行的动态\"], \"subtitleStrategy\": \"none\", \"fallbackStrategies\": [\"reuse_existing_material\"], \"preferredShotTypes\": [\"WIDE_SHOT\", \"MID_SHOT\"], \"requiredVisualFunctions\": [\"emotion_push\"], \"preferredCameraMovements\": [\"STATIC\"]}, {\"role\": \"outro\", \"label\": \"静态收束+引导闭环\", \"shotCount\": {\"max\": 3, \"min\": 2}, \"scriptHint\": \"孤树立于水面的长镜头保持完全静止，让水面波纹缓慢流动自然平复，最后弹出统一的平台搜索提示界面。\", \"description\": \"以水中伫立的孤树搭配日落远山的静态绝景收束全片情绪，最后跳转平台搜索引导页完成二次传播引导，形成完整闭环。\", \"segmentIndex\": 3, \"durationRange\": {\"max\": 6, \"min\": 4}, \"durationWeight\": 0.22, \"packagingDensity\": \"low\", \"requiredElements\": [\"水中孤树\", \"平台搜索引导界面\"], \"subtitleStrategy\": \"none\", \"fallbackStrategies\": [\"static_summary_card\"], \"preferredShotTypes\": [\"WIDE_SHOT\", \"CLOSE_UP\"], \"requiredVisualFunctions\": [\"static_summary_card\", \"cta_prompt\"], \"preferredCameraMovements\": [\"STATIC\"]}], \"totalSegments\": 4}, \"categoryExtensions\": {\"discoveredCategoryId\": \"vlog\", \"discoveredCategoryName\": \"日常记录\", \"dynamicExtensionFields\": [{\"fieldName\": \"scene_threshold\", \"fieldType\": \"DOUBLE\", \"fieldValue\": 0.25, \"description\": \"风景vlog判定有效硬切的阈值，超过该值的画面跳变计入正式镜头切换\"}, {\"fieldName\": \"cut_frequency\", \"fieldType\": \"STRING\", \"fieldValue\": \"low_frequency\", \"description\": \"全片以长镜头慢节奏为主，仅在场景跳转时做少量淡入淡出转场，无高频快切\"}, {\"fieldName\": \"motion_effects\", \"fieldType\": \"JSON\", \"fieldValue\": [\"slow_motion\", \"double_exposure_transition\", \"static_lockoff\"], \"description\": \"该品类常用的镜头运动与特效列表\", \"allowedValues\": [\"slow_motion\", \"double_exposure_transition\", \"static_lockoff\"]}, {\"fieldName\": \"audio_style\", \"fieldType\": \"STRING\", \"fieldValue\": \"soft_lyrical_background_music\", \"description\": \"全程以舒缓抒情的纯背景音乐作为听觉支撑，几乎无额外音效和旁白\"}], \"discoveredPromptOverrides\": {\"scriptAnalysis\": \"优先用低机位贴近水面的视角拍摄所有动态场景，最大化放大水面波纹和飞鸟掠水的沉浸感\"}}, \"packagingStructure\": {\"titleCards\": [], \"coverStyles\": [{\"layout\": \"full_scenery\", \"colorTone\": \"#FF7A00\", \"textElements\": []}], \"transitions\": [\"dissolve_fade\", \"double_exposure_mix\"], \"subtitleStyles\": []}}','800c86c7db848c08607b5524ac7c5cf87faa8e4